style.css:
/* PINK HAZE — Global */
/* i really want this to be global */

/* swap these values to change the palette */
:root {
  --my-pink: #ffc1d6;
  --my-pink-hover: #ffe0eb;
}

/* baby pink global typography */
html,
body,
p,
span,
div,
li,
label,
blockquote,
figcaption,
td,
th,
h1,
h2,
h3,
h4,
h5,
h6,
strong,
em,
small,
summary,
button,
a {
  color: var(--my-pink) !important;
}

/* softer pink on hover */
a:hover,
button:hover {
  color: var(--my-pink-hover) !important;
}

/* keep backgrounds transparent */
html,
body {
  background: transparent !important;
}

/* baby pink text selection */
::selection {
  background: #ffc1d6 !important;
  color: #ffffff !important;
}
